def tick_status(world: World, actor: Actor):
    if not actor.alive:
        return
    for name in list(actor.statuses):
        if name == "poison":
            damage = actor.receive(1)
            world.emit(Event("poison_tick", actor.actor_id, amount=damage))
            if not actor.alive:
                world.emit(Event("death", actor.actor_id))
            if actor.hp < 1:
                actor.hp = 1
        actor.statuses[name] -= 1
        if actor.statuses[name] <= 0:
            del actor.statuses[name]

